mapper.select:
SELECT * from ( SELECT CASE WHEN ISSUE.ISSUE_EDATE >= TO_DATE(#{iPlatformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE >= TO_DATE(#{iPlatformDate},'YYYY-MM-DD') THEN '01' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{iPlatformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{iPlatformDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is null THEN '02' WHEN (ISSUE.ISSUE_EDATE < TO_DATE(#{iPlatformDate},'YYYY-MM-DD') or ISSUE.TENDER_EDATE < TO_DATE(#{iPlatformDate},'YYYY-MM-DD')) and PRODUCT.CIRCULATION_CODE is not null THEN '03'
ELSE NULL END AS ISSUE_STAGE, PRODUCT_ADD.ISSUE_STATUS, PRODUCT.FINPROD_MARKET_ID, PRODUCT.FINPROD_ABBR, PRODUCT.FINPROD_NAME, PRODUCT.TRADE_MARKET, PRODUCT.REGIST_ORG, PRODUCT.ISSUER, PRODUCT.ISSUE_TYPE, ISSUE.ISSUE_CLASS ISSUE_CLASS, ISSUE.TENDER_TYPE, ISSUE.TENDER_TARGET, ISSUE.ISSUE_STYLE, ISSUE.PLAN_ISSUE_AMT, case when ISSUE.ISSUE_CLASS = '02' THEN ISSUE.ISSUE_SDATE else ISSUE.TENDER_SDATE end as SDATE_FORM, case when ISSUE.ISSUE_CLASS = '02' THEN ISSUE.ISSUE_EDATE else ISSUE.TENDER_EDATE end as EDATE_TO, ISSUE.PAY_EDATE, ISSUE.ASSIGN_REGDATE, case when PRODUCT.CIRCULATION_CODE is not null then TOTAL.SETTLE_DATE else PRODUCT_ADD.LISTING_DATE end as ONMARKET_DATE, case when PRODUCT.CIRCULATION_CODE is not null then PRODUCT2.FINPROD_MARKET_ID else PRODUCT_ADD.APPEAR_MARKET_ID end as APPEAR_MARKET_ID, PRODUCT.VDATE, PRODUCT.MDATE, PRODUCT_TYPE.TYPE_9, PRODUCT_TYPE.TYPE_10, PRODUCT_TYPE.TYPE_11, PRODUCT.COUPON_SPECIES, PRODUCT.CCY, PRODUCT.ISSUE_PRICE, ISSUE.INT_TYPE, ISSUE.PAY_CYCLE, ISSUE.REFER_YIELD, ISSUE.MIN_PER_TAMT, ISSUE.MAX_PER_UTAMT, PRODUCT.REMARK FROM FIN_PRODUCT PRODUCT LEFT JOIN FIN_PRODUCT_ADD PRODUCT_ADD ON PRODUCT.FINPROD_ID = PRODUCT_ADD.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON PRODUCT.FINPROD_ID = TOTAL.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON PRODUCT.FINPROD_ID = ISSUE.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE PRODUCT_TYPE ON PRODUCT.FINPROD_ID = PRODUCT_TYPE.FINPROD_ID AND PRODUCT_TYPE.BRANCH = '0' LEFT JOIN MST_CUSTOMER_INFO CUSTOMER_INFO ON PRODUCT.ISSUER = CUSTOMER_INFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT PRODUCT2 ON PRODUCT.CIRCULATION_CODE = PRODUCT2.FINPROD_ID
PRODUCT.FINPROD_TYPE2 = #{finProdType2,jdbcType=VARCHAR}
AND PRODUCT.FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
#{item}
) t ORDER BY t.ISSUE_STAGE, t.ISSUE_STATUS, t.TYPE_9, t.TYPE_10, t.TYPE_11, t.ISSUE_CLASS
